package com.goldenaccountant.app.domain
import com.goldenaccountant.app.data.*
import java.util.UUID
import javax.inject.Inject
data class DebitCredit(val accountId:String,val debitMinor:Long=0,val creditMinor:Long=0,val description:String="")
class AccountingEngine @Inject constructor(private val dao:JournalDao){suspend fun post(date:Long,referenceType:String,referenceId:String,description:String,lines:List<DebitCredit>){require(lines.isNotEmpty()){"القيد لا يحتوي على أسطر"};require(lines.all{it.debitMinor>=0&&it.creditMinor>=0}){"المبالغ لا يمكن أن تكون سالبة"};require(lines.all{(it.debitMinor==0L) xor (it.creditMinor==0L)}){"السطر يجب أن يكون مدينًا أو دائنًا"};val d=lines.sumOf{it.debitMinor};val c=lines.sumOf{it.creditMinor};require(d==c){"القيد غير متوازن"};val id=UUID.randomUUID().toString();dao.insertEntry(JournalEntry(id,date,referenceType,referenceId,description,System.currentTimeMillis()));dao.insertLines(lines.map{JournalEntryLine(UUID.randomUUID().toString(),id,it.accountId,it.debitMinor,it.creditMinor,it.description)})}}